    id: 'stats-173',
    category: 'statistics',
    question: '什么是归因模型（Attribution Model）？首次点击/末次点击/线性归因/时间衰减的区别？',
    answer:
      '归因模型（Attribution Model）是营销和产品分析中用于将转化（下单/注册/充值）的"功劳"分配到用户在转化前接触过的各个触点（渠道/广告/内容）上的统计规则。由于用户通常经历多个触点后才转化（如搜索广告 → 社交媒体帖 → 邮件 → 直接访问 → 购买），需要一套规则来回答"哪个渠道应该获得这次转化的功劳/多少功劳"。四种经典归因模型及其区别：(1) 首次点击归因（First-Touch Attribution）——将 100% 的转化功劳归于用户旅程中的第一个触点。逻辑：是第一个触点"引荐了用户认知产品/品牌"，没有它就后续转化可能不会发生。优点：极其简单实现；缺点：完全忽略了后续触点的影响，导致过度投资于"拉新"而轻视"促活"和"闭环"。(2) 末次点击归因（Last-Touch Attribution）——将 100% 的转化功劳归于用户旅程中的最后一个触点（转化前最后接触）。逻辑：最后一个触点提供了"最终的推动"完成转化。优点：简单，且与"最近一次广告花了钱才产生了转化"的直觉吻合；缺点：极其严重地高估了底部渠道（如品牌搜索广告——用户在搜品牌名时已经高度意向，广告只是"收获"而非"创造"了转化）。末次点击归因在 Google Analytics 等工具中长期是默认设置，但它不合理地"窃取"了上方渠道的贡献。(3) 线性归因（Linear Attribution）——将转化功劳平均分配给用户旅程中的所有触点。例如 5 个触点各得 20%。优点：更公平地承认每个触点的贡献；缺点：平均分配意味着将所有触点的"重要性"等同（无疑，转化前 30 天浏览的搜索广告和转化前 5 分钟的品牌搜索广告被等同），这显然与实际的效应衰减不符。(4) 时间衰减归因（Time Decay Attribution）——在时间上给予越接近转化时刻的触点越高的功劳权重（通常用指数衰减权重）。例如转化前 1 天的触点权重是转化前 7 天触点的 e^{-6λ} 倍。优点：符合心理学中"近因效应"——最近的接触对决策的影响通常最大；缺点：忽略了早期品牌认知在用户心智中长期建立的"隐性影响"。在实践中，一个 30 天前看到的创意广告可能是导致最终转化的根本原因，而时间衰减低估了它。除此之外还有：(5) 位置归因（Position-Based / U-Shaped Attribution）——将 40% 功劳分给首次触点，40% 分给最后触点，剩余 20% 均分给中间的所有触点。试图同时认可"拉新"和"闭环"的关键作用。(6) 数据驱动归因（Data-Driven Attribution, DDA）——使用统计/机器学习方法（如 Shapley 值——源于合作博弈论的"公平分配"解）根据各触点的反事实边际贡献对转化功劳进行分配。DDA 是目前最准确的归因方法，但需要足够的转化量训练模型且对实施技术和数据完整性要求高。归因模型的选择会严重影响渠道预算分配决策——例如从末次点击改为数据驱动归因通常会使搜索广告（品牌词）的功劳大幅下降，而上方渠道的展示/社交媒体获得更多认可，引致预算再分配。在 iOS 14+ 和 ATT（App Tracking Transparency）政策后，移动端的归因受到了极大限制（用户级跟踪减少），分析人员越来越多地依赖营销混合模型（MMM）等聚合级方法来做归因推断。',
