    id: 'stats-174',
    category: 'statistics',
    question: '如何设计 A/B 测试来验证产品改版效果？从指标选择到样本量计算的完整流程？',
    answer:
      '设计 A/B 测试验证产品改版效果需要遵循从假设到决策的完整统计框架。第一步：明确假设和成功标准——陈述清晰的因果假设："对于（用户群体），将（控制体验）改为（实验体验）将（方向性）改变（指标），因为（理由）"。例如："对于电商 App 首页用户，将商品推荐算法从协同过滤改为深度学习模型将提升 CTR（点击率），因为深度模型能更好捕捉用户的长尾偏好。" 同时定义成功标准——核心指标的最小业务意义效应（如 CTR 绝对提升 ≥ 1 个百分点），以及护栏指标（不能显著恶化的指标，如页面加载时间、用户投诉率）。第二步：选择实验单位、随机化单元和分流机制——实验单位（是用户还是设备还是会话？）必须与指标的独立性相匹配。选择稳定的用户 ID 进行哈希分流（MD5(userId + layer_seed) % 10000），确保同一用户始终在同一组。分流比例通常选择 50/50（等分使标准误最小），但如果担心新版本有严重 Bug，可先 5/95 运行（5% 实验组 = 安全试水）。第三步：指标体系的建立——核心指标（Primary Metric）通常 1-2 个"评估实验成功与否的决策依据"（如转化率、GMV）；诊断/辅助指标（Secondary Metrics）用于解释核心指标变化的原因（如各页面跳出率、搜索次数）。使用 OEC（Overall Evaluation Criterion）将多个重要指标加权合成为单一决策分数（如 0.5 × 转化率提升 + 0.3 × GMV + 0.2 × 留存）。第四步：样本量计算——核心公式（连续指标）n_per_group = 2σ²(Z_{α/2} + Z_β)² / δ²，其中 σ 为指标标准差（从历史数据估计），δ 为最小可检测效应 MDE，Z_{α/2} 为显著性水平分位数（α=0.05 双尾时 ≈ 1.96），Z_β 为统计功效分位数（1-β=0.8 时 ≈ 0.84）。对于二分类指标（如转化率 p），方差 = p(1-p)，样本量 n = (Z_{α/2} + Z_β)²[p₁(1-p₁) + p₂(1-p₂)] / (p₁-p₂)²。实例计算：基线转化率 p₀=10%，预期提升到 p₁=11%（MDE=1pp），则 n_per_group = (1.96+0.84)² × [0.1×0.9 + 0.11×0.89] / (0.01)² ≈ 14,700，即需要约 1.5 万用户/组。第五步：确定实验时长——实验时长需要覆盖至少 1-2 个完整的业务周期（如至少 1 个完整的周循环以捕捉周末效应差异），同时确保在设定的样本量下每日流量可达（如日活跃 1 万人，各组需要 1.5 万 → 至少需要 1.5 天，但还要等完整的周循环（7 天））。时间段太短的话会受"Novelty Effect"和外部事件干扰。第六步：线上监控和数据质量保证——在实验运行中持续监控 SRM（样本比例卡方检验）来确认分流无 Bug，监控各组的关键指标时间序列（但不过早做显著性检验以免 Peeking）。建议在实验平台预设"最小数据收集期（如 3 天）内隐藏分析结果"，避免实验者"Peeking"引发假阳性膨胀。第七步：统计分析和决策——实验结束后，对核心指标执行预注册的假设检验：(a) 如果 P ≤ α（如 0.05）且效应方向符合预期，且护栏指标未出现显著恶化 → 上线；(b) 如果 P > α 但置信区间未排除"最小业务意义效应"的上限 → 可能因为样本量不足（扩大实验或接受不确定继续）；(c) 如果效应方向与预期相反且显著 → 立即暂停并分析根因。第八步：长期效应评估——即使实验期显著，全量上线后也应保留小比例（如 1-5%）长尾对照组（Holdout Group）持续观察 3-6 个月，检验是否存在短期 AB 实验无法检测的长期效应衰减（Learning Effect / Novelty Effect）。切记：统计显著 ≠ 业务显著——若效应量为 0.1% 且 P=0.04，工程实现成本极高，业务上完全可能判定"不值得上线"（Practical Significance），样本量大了以后几乎总能找出统计显著差异。',
    tags: ['AB测试', '产品迭代', '实验设计', '样本量', 'hypothesis'],
    subTopic: '产品指标与分析',
    difficulty: 'hard',
